# Generated by Claude Opus 5.5 (claude.ai/code) · 2026-11-18
# Pester tests: whole runs - spool lifecycle, publish, isolation, fit, coverage.

BeforeAll {
    . (Join-Path $PSScriptRoot '../TestHelpers.ps1')
}

AfterAll {
    Remove-TestWork
}

Describe 'path size measurement' {
    It 'returns 0 for a non-existent path' {
        Get-PathSizeBytes -Path (Join-Path $Work 'nope') | Should -Be 0
    }
    It 'returns 0 for an empty directory without throwing (regression, under Stop)' {
        $ErrorActionPreference = 'Stop'
        $d = Join-Path $Work 'empty-dir'
        New-Item -ItemType Directory -Force -Path $d | Out-Null
        { Get-PathSizeBytes -Path $d } | Should -Not -Throw
        Get-PathSizeBytes -Path $d | Should -Be 0
    }
    It 'returns 0 for a directory containing only subdirectories' {
        $d = Join-Path $Work 'subdirs-only'
        New-Item -ItemType Directory -Force -Path (Join-Path $d 'wip') | Out-Null
        Get-PathSizeBytes -Path $d | Should -Be 0
    }
    It 'sums file sizes recursively' {
        $d = Join-Path $Work 'with-files'
        New-Item -ItemType Directory -Force -Path (Join-Path $d 'sub') | Out-Null
        Set-Content -LiteralPath (Join-Path $d 'a.bin') -Value ('x' * 100) -NoNewline
        Set-Content -LiteralPath (Join-Path $d 'sub/b.bin') -Value ('y' * 50) -NoNewline
        Get-PathSizeBytes -Path $d | Should -Be 150
    }
}

Describe 'spool lifecycle (wip -> stage -> ready)' {
    BeforeEach {
        $t = New-SpoolTestEnv -Prefix 'lc'
        $script:n = $t.N; $script:ev = $t.Ev; $script:root = $t.Root; $script:paths = $t.Paths
    }
    It 'publishes a successful backup to ready/ and clears wip/stage' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ | ConvertFrom-Json
        $runId = Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue
        $runId | Should -Not -BeNullOrEmpty
        (Test-Path (Join-Path $root 'ready/app/data.bin')) | Should -BeTrue
        (Test-Path (Join-Path $root 'ready/app/config.bin')) | Should -BeTrue
        (Test-Path (Join-Path $root 'wip/app')) | Should -BeFalse
        (Test-Path (Join-Path $root 'stage/app')) | Should -BeFalse
        $se = Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'app' } | Select-Object -First 1
        $se.status | Should -Be 'ok'
        $se.bytes | Should -BeGreaterThan 0
    }

    It 'does not publish a failed backup, but still runs recovery' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "boom", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        (Test-Path (Join-Path $root 'ready/app')) | Should -BeFalse
        $events = Get-BackupEvents -EventsPath $ev
        ($events | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'app' } | Select-Object -First 1).status | Should -Be 'fail'
        @($events | Where-Object { $_.type -eq 'step.begin' -and $_.step -eq 'start' }).Count | Should -BeGreaterThan 0
    }

    It 'replaces an unconsumed previous backup and notifies' {
        New-Item -ItemType Directory -Force -Path (Join-Path $root 'ready/app') | Out-Null
        Set-Content -LiteralPath (Join-Path $root 'ready/app/old.bin') -Value 'old'
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.replaced' }).Count | Should -BeGreaterThan 0
        (Test-Path (Join-Path $root 'ready/app/data.bin')) | Should -BeTrue
        (Test-Path (Join-Path $root 'ready/app/old.bin')) | Should -BeFalse
    }

    It 'reaps trash/ at run start' {
        New-Item -ItemType Directory -Force -Path (Join-Path $root 'trash/junk') | Out-Null
        Set-Content -LiteralPath (Join-Path $root 'trash/junk/f') -Value 'x'
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        (Test-Path (Join-Path $root 'trash/junk')) | Should -BeFalse
    }

    It 'sync-only (publishToReady=false) archives then leaves nothing in ready/' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "publishToReady": false,
    "syncArchive": { "script": "fixtures/mock-service.ps1", "env": {} },
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        (Test-Path (Join-Path $root 'ready/app')) | Should -BeFalse
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'step.end' -and $_.step -eq 'sync-archive' -and $_.status -eq 'ok' }).Count | Should -BeGreaterThan 0
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.end' })[-1].kept | Should -Be 'dropped'
    }

    It 'records what the run output tells: forced flags, service start with its estimate, where the copy is kept' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1", "publishToReady": true,
    "steps": [ { "name": "dump", "resources": [] } ] } } }
'@ | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -ForceAllJobs -WarningAction SilentlyContinue | Out-Null
        Invoke-BackupRun -Config $cfg -Paths $paths -WarningAction SilentlyContinue | Out-Null   # regular (covered: no backup)
        $evs = @(Get-BackupEvents -EventsPath $ev)
        @($evs | Where-Object { $_.type -eq 'run.begin' } | ForEach-Object { $_.forced }) -join ',' | Should -Be 'window,all,none'
        $starts = @($evs | Where-Object { $_.type -eq 'service.begin' })
        $starts[0].svc | Should -Be 'app'
        $starts[0].mandatory | Should -BeTrue
        $starts[0].estSec | Should -Be -1            # never backed up: unknown estimate
        $starts[1].estSec | Should -BeGreaterOrEqual 0
        @($evs | Where-Object { $_.type -eq 'service.end' })[0].kept | Should -Be 'ready'
        # lifecycle events say begin/end; start/stop are for starting a real service
        @($evs | Where-Object { $_.type -match '\.(start|stop)$' }).Count | Should -Be 0
    }

    It 'sync-only (publishToReady=false): a sync failure retains nothing and fails the service' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "publishToReady": false,
    "syncArchive": { "script": "fixtures/mock-service.ps1", "env": { "MOCK_ARCHIVE_FAIL": "1" } },
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.syncfail' }).Count | Should -BeGreaterThan 0
        # config honored: not force-published to a ready/ nobody consumes
        (Test-Path (Join-Path $root 'ready/app')) | Should -BeFalse
        # and nothing was archived -> the service is a failure, not a silent ok
        $endE = @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'app' })
        $endE[-1].status | Should -Be 'fail'
        $endE[-1].kept | Should -Be 'dropped'
    }

    It 'publishToReady=true: a sync failure still publishes to ready/ and stays ok (archiver has it)' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "publishToReady": true,
    "syncArchive": { "script": "fixtures/mock-service.ps1", "env": { "MOCK_ARCHIVE_FAIL": "1" } },
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ | ConvertFrom-Json
        $runId = Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.syncfail' }).Count | Should -BeGreaterThan 0
        (Test-Path (Join-Path $root 'ready/app/data.bin')) | Should -BeTrue
        $endE = @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'app' })
        $endE[-1].status | Should -Be 'ok'
        # the dead-man's-switch report must still surface the archive failure
        (Format-RunReport -EventsPath $ev -RunId $runId) | Should -Match 'archive failed'
    }

    It 'service-level env feeds the archiver (unified env scope chain)' {
        $dest = Join-Path $Work "svcenv-$n"
        # ARCHIVE_DEST/ARCHIVE_KEEP live only in the service's own env, not in a
        # top-level block nor in syncArchive.env -> the archiver must still see them
        $cfg = (@'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "env": { "ARCHIVE_DEST": "__DEST__", "ARCHIVE_KEEP": "3" },
    "publishToReady": true,
    "syncArchive": { "script": "../src/recipes/archive-copy.ps1" },
    "steps": [ { "name": "dump", "resources": [] }, { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ -replace '__DEST__', ($dest -replace '\\', '/')) | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        (Test-Path (Join-Path $dest 'app')) | Should -BeTrue
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.archived' -and $_.svc -eq 'app' }).Count | Should -BeGreaterThan 0
    }

    It 'isolates a broken service: it fails but other services still run' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": {
    "broken": { "enabled": true, "mandatory": true, "script": "fixtures/throwing-recipe.ps1",
      "steps": [ { "name": "dump", "resources": [] } ] },
    "good": { "enabled": true, "mandatory": false, "script": "fixtures/mock-service.ps1",
      "steps": [ { "name": "dump", "resources": [] }, { "name": "start", "resources": [], "alwaysRun": true } ] }
  } }
'@ | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        $events = Get-BackupEvents -EventsPath $ev
        ($events | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'broken' } | Select-Object -First 1).status | Should -Be 'fail'
        ($events | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'good' } | Select-Object -First 1).status | Should -Be 'ok'
        @($events | Where-Object { $_.type -eq 'run.end' }).Count | Should -Be 1
    }

    It 'recipe registration output does not taint the returned run id' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/noisy-recipe.ps1",
    "steps": [ { "name": "dump", "resources": [] } ] } } }
'@ | ConvertFrom-Json
        $runId = Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue
        $runId | Should -BeOfType [string]
        $runId | Should -Match '^\d{8}-\d{6}-'
    }

    It 'runs the guaranteed first job but defers a second that will not fit' {
        # window centred on now so we are inside it with ~2h left
        $now = Get-Date
        $open = $now.AddHours(-2).ToString('HH:mm')
        $close = $now.AddHours(2).ToString('HH:mm')
        # both never-succeeded, both with a huge estimate (>> the ~2h left) -> neither "fits"
        foreach ($s in 'first', 'second') {
            Add-Content -LiteralPath $ev -Value (@{ ts = '2026-11-06T00:00:00+00:00'; type = 'step.end'; svc = $s; step = 'dump'; status = 'ok'; durationSec = 100000 } | ConvertTo-Json -Compress)
        }
        $cfg = (@'
{ "window": { "open": "__OPEN__", "close": "__CLOSE__" },
  "services": {
    "first":  { "enabled": true, "mandatory": false, "script": "fixtures/mock-service.ps1",
      "steps": [ { "name": "dump", "resources": [] }, { "name": "start", "resources": [], "alwaysRun": true } ] },
    "second": { "enabled": true, "mandatory": false, "script": "fixtures/mock-service.ps1",
      "steps": [ { "name": "dump", "resources": [] }, { "name": "start", "resources": [], "alwaysRun": true } ] }
  } }
'@ -replace '__OPEN__', $open -replace '__CLOSE__', $close) | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -WarningAction SilentlyContinue -InformationAction SilentlyContinue | Out-Null
        $events = Get-BackupEvents -EventsPath $ev
        # 'first' is the guaranteed job: it runs even though it does not fit
        ($events | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'first' } | Select-Object -Last 1).status | Should -Be 'ok'
        (Test-Path (Join-Path $root 'ready/first')) | Should -BeTrue
        # 'second' does not fit and the guarantee is already spent -> deferred, not run
        ($events | Where-Object { $_.type -eq 'service.skip' -and $_.svc -eq 'second' -and $_.reason -eq 'deferred' }).Count | Should -BeGreaterThan 0
        (Test-Path (Join-Path $root 'ready/second')) | Should -BeFalse
    }

    It 'skips a service already covered for its period (no backup produced)' {
        $dest = Join-Path $Work "cov-$n"
        # a gfsy archive 1h ago -> the archiver reports covered for the day
        $arch = Join-Path (Join-Path (Join-Path $dest 'app') 'daily') 'seed'
        New-Item -ItemType Directory -Force -Path $arch | Out-Null
        Add-Content -LiteralPath $ev -Value (@{ ts = (Get-Date).AddHours(-1).ToString('o'); type = 'service.archived'; svc = 'app'; tier = 'daily'; path = $arch } | ConvertTo-Json -Compress)
        $cfg = (@'
{ "window": { "open": "00:00", "close": "23:59" },
  "env": { "ARCHIVE_DEST": "__DEST__" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "syncArchive": { "script": "../src/recipes/archive-gfsy.ps1" },
    "steps": [ { "name": "dump", "resources": [] }, { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ -replace '__DEST__', ($dest -replace '\\', '/')) | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -WarningAction SilentlyContinue -InformationAction SilentlyContinue | Out-Null
        $events = Get-BackupEvents -EventsPath $ev
        ($events | Where-Object { $_.type -eq 'service.skip' -and $_.svc -eq 'app' -and $_.reason -eq 'covered' }).Count | Should -BeGreaterThan 0
        (Test-Path (Join-Path $root 'ready/app')) | Should -BeFalse
    }

    It 'coverage grace: a backup just under the period still runs (timer-jitter fix)' {
        $dest = Join-Path $Work "covg-$n"
        # a gfsy archive 1 second short of 24h ago: with no grace margin this reads as
        # overdue ~0.99999 and is wrongly skipped as covered (the missed-nightly bug)
        $arch = Join-Path (Join-Path (Join-Path $dest 'app') 'daily') 'seed'
        New-Item -ItemType Directory -Force -Path $arch | Out-Null
        Add-Content -LiteralPath $ev -Value (@{ ts = (Get-Date).AddSeconds(-86399).ToString('o'); type = 'service.archived'; svc = 'app'; tier = 'daily'; path = $arch } | ConvertTo-Json -Compress)
        $cfg = (@'
{ "window": { "open": "00:00", "close": "23:59" },
  "env": { "ARCHIVE_DEST": "__DEST__" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "syncArchive": { "script": "../src/recipes/archive-gfsy.ps1" },
    "steps": [ { "name": "dump", "resources": [] }, { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ -replace '__DEST__', ($dest -replace '\\', '/')) | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -WarningAction SilentlyContinue -InformationAction SilentlyContinue | Out-Null
        $events = Get-BackupEvents -EventsPath $ev
        # not skipped as covered, and it actually produced a backup
        @($events | Where-Object { $_.type -eq 'service.skip' -and $_.svc -eq 'app' -and $_.reason -eq 'covered' }).Count | Should -Be 0
        ($events | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'app' } | Select-Object -Last 1).status | Should -Be 'ok'
    }

    It 'preflight: an invalid service is skipped with no steps run (no downtime); others still run' -Skip:($IsWindows) {
        $dest = Join-Path $Work "valrun-$n"
        $cfg = (@'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": {
    "bad":  { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
      "syncArchive": { "script": "../src/recipes/archive-restic.ps1",
        "env": { "RESTIC_REPOSITORY": "/tmp/repo", "RESTIC_BIN": "__STUB__", "RESTIC_PASSWORD_FILE": "/no/such/secret.pwd" } },
      "steps": [ { "name": "dump" }, { "name": "start", "alwaysRun": true } ] },
    "good": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
      "publishToReady": true,
      "syncArchive": { "script": "../src/recipes/archive-copy.ps1", "env": { "ARCHIVE_DEST": "__DEST__" } },
      "steps": [ { "name": "dump" }, { "name": "start", "alwaysRun": true } ] }
  } }
'@ -replace '__STUB__', ($script:resticStub -replace '\\', '/') -replace '__DEST__', ($dest -replace '\\', '/')) | ConvertFrom-Json
        $runId = Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -ForceAllJobs -WarningAction SilentlyContinue
        $events = Get-BackupEvents -EventsPath $ev
        # bad: flagged invalid, counted failed, and crucially NO step events (never taken down)
        $badEnd = @($events | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'bad' })[-1]
        $badEnd.status | Should -Be 'fail'
        $badEnd.reason | Should -Be 'invalid'
        @($events | Where-Object { ($_.type -eq 'step.begin' -or $_.type -eq 'step.end') -and $_.svc -eq 'bad' }).Count | Should -Be 0
        # good: ran and archived despite the other service being invalid
        (@($events | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'good' })[-1]).status | Should -Be 'ok'
        @($events | Where-Object { $_.type -eq 'service.archived' -and $_.svc -eq 'good' }).Count | Should -BeGreaterThan 0
        # the report surfaces the invalid reason
        $report = Format-RunReport -EventsPath $ev -RunId $runId
        $report | Should -Match '(?m)^  bad\s+INVALID'
        $report | Should -Match '(?m)^      - '
    }
}
